<?php require 'config.php';auth();$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';try{if($action==='delete'){$s=$p->prepare('DELETE FROM inquiries WHERE id=?');$s->execute([$id]);flash('Inquiry deleted.');}else{$st=$_POST['status']??'New';if(!in_array($st,['New','Contacted','Resolved'],true))throw new RuntimeException('Invalid status.');$s=$p->prepare('UPDATE inquiries SET status=? WHERE id=?');$s->execute([$st,$id]);flash('Inquiry status updated.');}}catch(Throwable $e){flash('Unable to update inquiry.','error');}header('Location: inquiries.php');exit;}$q='%'.trim($_GET['q']??'').'%';$s=$p->prepare('SELECT * FROM inquiries WHERE name LIKE ? OR email LIKE ? OR subject LIKE ? ORDER BY created_at DESC');$s->execute([$q,$q,$q]);$rows=$s->fetchAll();$page='Inquiries';require 'includes/header.php';?><div class="heading"><div><p class="eyebrow">INBOUND COMMUNICATION</p><h1>Inquiries</h1><p class="muted">Track contact messages and follow-up status.</p></div></div><section class="panel form-panel"><div class="panel-head"><div><h2>Add inquiry</h2><p>Record a message received from a potential client.</p></div></div><form class="form-grid" method="post" action="inquiry_save.php"><input type="hidden" name="csrf" value="<?=e(token())?>"><label>Name *<input name="name" required></label><label>Email *<input name="email" type="email" required></label><label>Phone<input name="phone"></label><label>Subject<input name="subject"></label><label class="wide">Message<textarea name="message" rows="2"></textarea></label><div class="wide form-actions"><button class="btn primary">Save inquiry</button></div></form></section><section class="panel listing"><div class="panel-head"><h2>Inquiry inbox <small><?=count($rows)?></small></h2><form class="search"><input name="q" placeholder="Search inquiries..." value="<?=e($_GET['q']??'')?>"><button class="btn">Search</button></form></div><div class="table-wrap"><table><thead><tr><th>Contact</th><th>Subject / message</th><th>Date</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?><small><?=e($r['email'])?></small></td><td><?=e($r['subject']?:'General inquiry')?><small><?=e($r['message'])?></small></td><td><?=date('M j, Y',strtotime($r['created_at']))?></td><td><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="status"><select name="status" onchange="this.form.submit()"><?php foreach(['New','Contacted','Resolved'] as $st):?><option <?=($r['status']===$st)?'selected':''?>><?=$st?></option><?php endforeach;?></select></form></td><td><form method="post" onsubmit="return confirm('Delete inquiry?')"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require 'includes/footer.php';?>
